#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char word[101];
    scanf("%100s", word);
    int i = 0, j = strlen(word) - 1;
    int same = 1;
    while (i < j) {
        if (tolower(word[i]) != tolower(word[j])) {
            same = 0;
            break;
        }
        i++;
        j--;
    }
    printf("%s\n", same ? "YES" : "NO");
    return 0;
}
